        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def _parse_hint(self, hint: str) -> tuple:
        parts = hint.split()
        operation = parts[0]
        condition = ' '.join(parts[1:])
        return operation, condition

    def _check_condition(self, row: int, col: int, operation: str, condition: str) -> bool:
        if operation == 'sum':
            val = row + col
        elif operation == 'product':
            val = row * col
        elif operation == 'difference':
            val = abs(row - col)
        else:
            return False

        if condition.startswith('is less than'):
            v1 = int(condition.split()[-1])
            return val < v1
        elif condition.startswith('is greater than'):
            v1 = int(condition.split()[-1])
            return val > v1
        elif condition.startswith('contains digit'):
            v1 = int(condition.split()[-1])
            return str(v1) in str(val)
        elif condition == 'is even':
            return val % 2 == 0
        elif condition == 'is odd':
            return val % 2 == 1
        elif condition.startswith('is between'):
            parts = condition.split()
            v1 = int(parts[2])
            v2 = int(parts[4])
            return v1 <= val <= v2
        return False

    def _get_valid_moves(self, grid: List[List[int]], hint: str) -> List[tuple]:
        operation, condition = self._parse_hint(hint)
        valid_moves = []
        for row in range(len(grid)):
            for col in range(len(grid[0])):
                if grid[row][col] == 0 and self._check_condition(row+1, col+1, operation, condition):
                    valid_moves.append((row+1, col+1))
        return valid_moves

    def _is_winning_path(self, grid: List[List[int]], player: int, start_positions: List[tuple], end_condition) -> bool:
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        visited = set()

        for start in start_positions:
            if grid[start[0]-1][start[1]-1] != player:
                continue
            stack = [start]
            visited = set()

            while stack:
                r, c = stack.pop()
                if (r, c) in visited:
                    continue
                visited.add((r, c))

                if end_condition(r, c):
                    return True

                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 1 <= nr <= rows and 1 <= nc <= cols and grid[nr-1][nc-1] == player:
                            stack.append((nr, nc))
        return False

    def _get_priority_moves(self, grid: List[List[int]], valid_moves: List[tuple], player: int) -> List[tuple]:
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        priority_moves = []

        for move in valid_moves:
            temp_grid = [row.copy() for row in grid]
            temp_grid[move[0]-1][move[1]-1] = player

            if player == 1:
                start_positions = [(r, 1) for r in range(1, rows+1)]
                end_condition = lambda r, c: c == cols
            else:
                start_positions = [(1, c) for c in range(1, cols+1)]
                end_condition = lambda r, c: r == rows

            if self._is_winning_path(temp_grid, player, start_positions, end_condition):
                priority_moves.append(move)

        return priority_moves

    def _get_blocking_moves(self, grid: List[List[int]], valid_moves: List[tuple], player: int) -> List[tuple]:
        opponent = 2 if player == 1 else 1
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        blocking_moves = []

        for move in valid_moves:
            temp_grid = [row.copy() for row in grid]
            temp_grid[move[0]-1][move[1]-1] = player

            if opponent == 1:
                start_positions = [(r, 1) for r in range(1, rows+1)]
                end_condition = lambda r, c: c == cols
            else:
                start_positions = [(1, c) for c in range(1, cols+1)]
                end_condition = lambda r, c: r == rows

            if self._is_winning_path(temp_grid, opponent, start_positions, end_condition):
                blocking_moves.append(move)

        return blocking_moves

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        valid_moves = self._get_valid_moves(current_grid, current_hint)

        if not valid_moves:
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )

        # First look for winning moves
        priority_moves = self._get_priority_moves(current_grid, valid_moves, player_idx)
        if priority_moves:
            position_selected = priority_moves[0]
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=position_selected, type='custom')]
            )

        # Then look for blocking moves
        blocking_moves = self._get_blocking_moves(current_grid, valid_moves, player_idx)
        if blocking_moves:
            position_selected = blocking_moves[0]
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=position_selected, type='custom')]
            )

        # If no priority moves, select first valid move
        position_selected = valid_moves[0]
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

